export function getActStepStatus(activityID: any,stepID: any,stepStatus: any,stepNum: any) {
  const act = getActStatus(activityID,stepNum)
  const steps = act!.steps
  let status
  steps.forEach((e,index) => {
    const id = index + 1
    if(id === stepID) {
      status = e
    }
  });
  return status
}

export function getActStatus(activityID: any, stepNum: any) {
  const activityList = window.localStorage.getItem('aveActStautsList')
  let act
  if(activityList) {
    const actList = JSON.parse(activityList)
    let isNew = true
    actList.forEach((e:any) => {
      if(e.activityID === activityID) {
        isNew = false
        act = e
      }
    });
    if(isNew) {
      let steps = []
      let final_status = 0
      for(let i=0;i<stepNum;i++){
        steps.push(0)
      }
      const actNew = {
        activityID: activityID,
        steps: steps,
        final_status: final_status
      }
      actList.push(actNew)
      act = actNew
    }
  } else {
    let actList = []
    let steps = []
    let final_status = 0
    for(let i=0;i<stepNum;i++){
      steps.push(0)
    }
    const actNew = {
      activityID: activityID,
      steps: steps,
      final_status: final_status
    }
    actList.push(actNew)
    window.localStorage.setItem('aveActStautsList',JSON.stringify(actList))
    act = actNew
  }
  return act
}
export function setTaskStatus(activityID: any,stepID: any,stepStatus: any,stepNum: any) {
  const activityList = window.localStorage.getItem('aveActStautsList')
  if(activityList) {
    const actList = JSON.parse(activityList)
    let isNew = true
    actList.forEach((e:any) => {
      if(e.activityID === activityID) {
        isNew = false
        e.steps.forEach((a:any,index:any) => {
          const id = index +1
          if(id === stepID) {
            e.steps[index] = stepStatus
          }
        });
      }
    });
    if(isNew) {
      let steps = []
      let final_status = 0
      for(let i=0;i<stepNum;i++){
        steps.push(0)
      }
      steps.forEach((e,index) => {
        const id = index +1
        if(stepID === id) {
          steps[index] = stepStatus
        }
      });
      const act = {
        activityID: activityID,
        steps: steps,
        final_status: final_status
      }
      actList.push(act)
    }
    window.localStorage.setItem('aveActStautsList',JSON.stringify(actList))
  } else {
    let actList = []
    let steps = []
    let final_status = 0
    for(let i=0;i<stepNum;i++){
      steps.push(0)
    }
    steps.forEach((e,index) => {
      const id = index +1
      if(stepID === id) {
        steps[index] = stepStatus
      }
    });
    const act = {
      activityID: activityID,
      steps: steps,
      final_status: final_status
    }
    actList.push(act)
    window.localStorage.setItem('aveActStautsList',JSON.stringify(actList))
  }
}

export function clearTask() {
  window.localStorage.removeItem('aveActStautsList');
  location.reload()
}